/* eslint-disable no-undef */
/**
 * Sahaj Shiksha service worker (Module 4 scaffold).
 *
 * Written by hand rather than generated by a framework plugin, for two reasons:
 *  1. The caching policy here is a *product* decision (cache the shell and the
 *     current lesson, budget the rest) and belongs in reviewable code, not in a
 *     config object.
 *  2. It must work on browsers a build plugin has not been tested against.
 *
 * What is implemented now:
 *  - precache of the shell routes so the app opens with no network;
 *  - stale-while-revalidate for same-origin static assets;
 *  - network-first for navigations, falling back to the cached page, then to
 *    the offline page;
 *  - versioned caches, with old versions deleted on activation.
 *
 * What is deliberately NOT here yet (Module 4 work):
 *  - IndexedDB queue for quiz submissions and progress events;
 *  - background sync;
 *  - LRU budgeting for cached audio.
 * Those need the API's `/api/sync/batch` endpoint to be meaningful, which is why
 * the queue is added together with the sync client rather than before it.
 */

const CACHE_VERSION = 'v2';
const SHELL_CACHE = `sahaj-shell-${CACHE_VERSION}`;
const RUNTIME_CACHE = `sahaj-runtime-${CACHE_VERSION}`;

/**
 * Only routes worth having offline on day one. Deliberately short: a tablet with
 * 8 GB of storage shared between children must not fill up on install. The module
 * routes are cached on install now that they are live; the rest of the library
 * still lands in the runtime cache on first open.
 */
const PRECACHE_URLS = [
  '/',
  '/offline',
  '/accessibility',
  '/lessons',
  '/quizzes',
  '/progress',
  '/manifest.webmanifest',
  '/icon.svg',
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(SHELL_CACHE);
      // Added one by one: `addAll` rejects the whole install if any single URL
      // fails, which would make the app permanently un-cacheable behind a proxy
      // that blocks one asset.
      await Promise.all(
        PRECACHE_URLS.map((url) =>
          cache.add(new Request(url, { cache: 'reload' })).catch(() => undefined),
        ),
      );
      // Intentionally NOT calling skipWaiting(): swapping the shell while a
      // learner is mid-lesson loses their place. The new worker takes over on
      // the next navigation.
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter((key) => key !== SHELL_CACHE && key !== RUNTIME_CACHE)
          .map((key) => caches.delete(key)),
      );
      if (self.registration.navigationPreload) {
        await self.registration.navigationPreload.disable();
      }
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;

  // Never interfere with non-GET traffic. Submitting a quiz answer offline is
  // the queue's job, and a cached POST response would be a lie.
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (request.mode === 'navigate') {
    event.respondWith(handleNavigation(request));
    return;
  }

  if (isCacheableAsset(url.pathname)) {
    event.respondWith(staleWhileRevalidate(request, RUNTIME_CACHE));
  }
});

/** Network first, then the cached page, then the offline page. */
async function handleNavigation(request) {
  try {
    const response = await fetch(request);
    const cache = await caches.open(SHELL_CACHE);
    cache.put(request, response.clone()).catch(() => undefined);
    return response;
  } catch {
    const cached = await caches.match(request);
    if (cached) return cached;
    const shell = await caches.match('/');
    if (shell) return shell;
    const offline = await caches.match('/offline');
    if (offline) return offline;
    return new Response('Offline', { status: 503, headers: { 'Content-Type': 'text/plain' } });
  }
}

/** Serve from cache immediately, refresh in the background. */
async function staleWhileRevalidate(request, cacheName) {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);
  const network = fetch(request)
    .then((response) => {
      if (response.ok) cache.put(request, response.clone()).catch(() => undefined);
      return response;
    })
    .catch(() => undefined);

  return cached ?? (await network) ?? new Response('', { status: 504 });
}

function isCacheableAsset(pathname) {
  return (
    pathname.startsWith('/_next/static/') ||
    pathname.startsWith('/fonts/') ||
    pathname.startsWith('/audio/') ||
    pathname.startsWith('/icons/')
  );
}
